// Kolíska Hermle: používateľom dodané STL (Meshy_AI_Industrial_Rotary_Positioner_20261105_texture.stl),
// zjednodušené na 14000 trojuholníkov. Binárne (Uint16) namiesto JSON: menší balík a bez parsovania JSON.
// Súradnice sú kvantované krokom 0,002 / 0,001 / 0,001 (najväčšia odchýlka 0.0010).
export const CRADLE_SOURCE = "Meshy_AI_Industrial_Rotary_Positioner_20261105_texture.stl";
const N = 6998, M = 42000, MIN = [-46.574, -23.833, 0.002], STEP = [0.002, 0.001, 0.001];
const DATA = '';
let cache = null;
// vráti { positions: Float32Array (x, z, h ako v pôvodnom STL), indices: Uint16Array }
export function cradleData() {
  if (cache) return cache;
  const bin = atob(DATA), bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const words = new Uint16Array(bytes.buffer), positions = new Float32Array(N * 3);
  for (let i = 0; i < N * 3; i++) { const a = i % 3; positions[i] = MIN[a] + words[i] * STEP[a]; }
  cache = { positions, indices: words.slice(N * 3, N * 3 + M) };
  return cache;
}
